function isSchemaCompilerClass(candidate: unknown): candidate is SchemaCompilerClass {
  return typeof candidate === 'function';
}

function validateToolInput(validate: CompiledValidator, input: Record<string, unknown>): ValidationRejection | null {
  const valid = validate(input);
  if (valid === true) return null;
  const issues = validate.errors ?? [];
  const details = issues.map(describeSchemaIssue);
  const fields = [...new Set(details.map(detail => detail.fieldPath))];
  const summaryText = details.map(detail => detail.summary).join('; ');
  return {
    fields,
    message: `Invalid tool input: ${summaryText || 'input did not match schema'}`,
