const ISSUE_FORMATTERS: Record<string, (fieldPath: string, params: Record<string, unknown>) => string> = {
  required: fieldPath => `field "${fieldPath}" is required`,
  type: (fieldPath, params) => {
    const expectedType = Array.isArray(params.type) ? params.type.join(' | ') : String(params.type);
