function resolveFieldPath(issue: SchemaIssue): string {
  const rawPath = issue.instancePath ?? issue.dataPath ?? '';
  const basePath = rawPath.replace(/^[/.]/, '').replaceAll('/', '.');
  const missingProperty =
    issue.keyword === 'required' && typeof issue.params?.missingProperty === 'string'
      ? issue.params.missingProperty
      : '';
  if (!missingProperty) return basePath || '<root>';
  return basePath ? `${basePath}.${missingProperty}` : missingProperty;
