import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('passes valid input including undeclared extra properties through unchanged and rejects invalid enum values', async () => {
    const registry = new ToolRegistry();
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_forecast',
        description: 'Forecast lookup',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string', minLength: 2},
            units: {type: 'string', enum: ['celsius', 'fahrenheit']},
          },
          required: ['location'],
        },
      },
      async input => {
        receivedInputs.push(input);
        return 'ok';
      }
    );

    const accepted = await registry.execute('get_forecast', {
      location: 'Berlin',
      units: 'celsius',
      traceId: 'extra-42',
    });
    const rejectedEnum = await registry.execute('get_forecast', {
      location: 'Berlin',
      units: 'kelvin',
    });
    const rejectedMinLength = await registry.execute('get_forecast', {
      location: 'B',
    });

    expect({
      accepted,
      receivedInputs,
      enumMentionsUnits: rejectedEnum.result.includes('units') && rejectedEnum.result.includes('celsius'),
      enumOmitsValue: !rejectedEnum.result.includes('kelvin'),
      minLengthMentionsLocation: rejectedMinLength.result.includes('location'),
    }).toEqual({
      accepted: {result: 'ok'},
      receivedInputs: [{location: 'Berlin', units: 'celsius', traceId: 'extra-42'}],
      enumMentionsUnits: true,
      enumOmitsValue: true,
      minLengthMentionsLocation: true,
    });
  });

  it('throws Unknown tool when executing an unregistered tool name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('unregistered_tool', {})).rejects.toThrow('Unknown tool: unregistered_tool');
  });

  it('validates function-valued definitions against the schema returned on each call while caching by schema object', async () => {
    const registry = new ToolRegistry();
    const schemaRequiringCity = {
      type: 'object',
      properties: {city: {type: 'string'}},
      required: ['city'],
    };
    const schemaRequiringCountry = {
      type: 'object',
      properties: {country: {type: 'string'}},
      required: ['country'],
    };
    let activeSchema: Record<string, unknown> = schemaRequiringCity;
    registry.register(
      () => ({
        name: 'dynamic_lookup',
        description: 'Switches schema dynamically',
        inputSchema: activeSchema,
      }),
      async input => JSON.stringify(input)
    );

    const firstPass = await registry.execute('dynamic_lookup', {city: 'Amsterdam'});
    const cachedRejection = await registry.execute('dynamic_lookup', {});
    activeSchema = schemaRequiringCountry;
    const swappedRejection = await registry.execute('dynamic_lookup', {city: 'Amsterdam'});
    const swappedPass = await registry.execute('dynamic_lookup', {country: 'NL'});

    expect({
      firstPass: firstPass.result,
      cachedMentionsCity: cachedRejection.result.includes('city'),
      swappedMentionsCountry: swappedRejection.result.includes('country'),
      swappedPass: swappedPass.result,
    }).toEqual({
      firstPass: '{"city":"Amsterdam"}',
      cachedMentionsCity: true,
      swappedMentionsCountry: true,
      swappedPass: '{"country":"NL"}',
    });
  });
});

